import dataclasses as _dc

a = Money(1000, "KES")
assert a == Money(1000, "KES") and a != Money(1000, "TZS")
assert a + Money(250, "KES") == Money(1250, "KES")
assert {a: "ok"}[Money(1000, "KES")] == "ok"
