    a.amount_cents = 5
except _dc.FrozenInstanceError:
    pass
else:
    raise AssertionError("Money must be immutable (frozen)")
for bad_currency in ["kes", "KE", "KESH", "K3S", ""]:
    try:
        Money(1, bad_currency)
    except ValueError:
        pass
    else:
        raise AssertionError(f"currency {bad_currency!r} should be rejected")
for bad_amount in [1.5, "100", True, None]:
    try:
        Money(bad_amount, "EUR")
    except TypeError:
        pass
    else:
        raise AssertionError(f"amount {bad_amount!r} should raise TypeError")
try:
    Money(1, "EUR") + Money(1, "USD")
except ValueError:
    pass
else:
    raise AssertionError("adding different currencies should raise ValueError")
assert Money(1000, "EUR").split(3) == [Money(334, "EUR"), Money(333, "EUR"), Money(333, "EUR")]
assert Money(2, "JPY").split(4) == [Money(1, "JPY"), Money(1, "JPY"), Money(0, "JPY"), Money(0, "JPY")]
