import re
from dataclasses import dataclass

@dataclass(frozen=True)
class Money:
    amount_cents: int
    currency: str

    def __post_init__(self):
        if type(self.amount_cents) is not int:
            raise TypeError(f"amount_cents must be an int, not {type(self.amount_cents).__name__}")
        if not isinstance(self.currency, str) or not re.fullmatch(r"[A-Z]{3}", self.currency):
            raise ValueError(f"currency must be three upper-case letters, not {self.currency!r}")

    def __add__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        if other.currency != self.currency:
            raise ValueError(f"cannot add {self.currency} and {other.currency}")
        return Money(self.amount_cents + other.amount_cents, self.currency)

    def split(self, n):
        if n < 1:
            raise ValueError("split needs at least one share")
        base, extra = divmod(self.amount_cents, n)
        return [Money(base + 1, self.currency)] * extra + [Money(base, self.currency)] * (n - extra)

